<style>
@page{margin:28px 32px 46px}body{font-family:DejaVu Sans,sans-serif;font-size:10px;line-height:1.5;color:#243342;margin:0}h1,h2,h3,p{margin:0}h1{font-size:25px;letter-spacing:1px}h2{font-size:14px;margin:5px 0}h3{font-size:11px;margin:10px 0 5px}p{white-space:pre-line;word-wrap:break-word}table{width:100%;border-collapse:collapse;table-layout:fixed}td{vertical-align:top}th,td{word-wrap:break-word}.right{text-align:right}.muted,.label{color:#657787}.label{font-size:8px;letter-spacing:.8px;text-transform:uppercase}.header{border-top:3px solid {{ $business->brand_color }};border-bottom:1px solid #dce4ea;background:#f6f8fa}.header td{padding:16px}.header .dates td{padding:8px 16px}.logo{max-height:46px;max-width:150px;margin-bottom:6px}.parties{margin:22px 0}.parties td{width:50%;padding-right:20px}.reference{border-top:1px solid #e1e7ed;padding:10px 0;margin-bottom:12px}.status{font-size:9px;color:#506573;text-transform:uppercase}.items thead{display:table-header-group}.items th{background:#f0f4f7;text-align:left;font-size:9px;padding:10px 7px;border-bottom:1px solid #d7e1e8}.items td{padding:11px 7px;border-bottom:1px solid #e5ebf0}.items tr{page-break-inside:avoid}.items .right{text-align:right}.amount{font-weight:bold}.totals{width:58%;margin-left:42%;margin-top:17px;page-break-inside:avoid}.totals td{padding:6px 8px}.totals .grand td{background:#edf3f6;border-top:2px solid {{ $business->brand_color }};font-size:13px;font-weight:bold;padding:10px 8px}.section{border-top:1px solid #e0e7ed;padding-top:12px;margin-top:20px}.bank-block{background:#f7f9fb;padding:10px 12px;margin:8px 0;page-break-inside:avoid}.footer{position:fixed;bottom:-28px;left:0;right:0;border-top:1px solid #e0e7ed;padding-top:6px;font-size:8px;color:#657787}.footer .page:after{content:counter(page)}.note{margin-top:6px}
